th.pi r5)) q p return Vector3() def simulatepbf(particles, dt, numiterations, boundary, kernelradius, restdensity): # particles: list of dicts with keys: 'pos', 'vel', 'mass', 'oldpos', 'predictedpos', 'posdelta', 'gradnormsq' # boundary: object with 'confine(pos)' method # 1. Prediction for p in particles: acc = p.get('fext', Vector3()) / p['mass'] p['predictedpos'] = p['pos'] + dt p['vel'] + dt2 acc # 2. Constraint Solving for p in particles: p['posdelta'] = Vector3(0, 0, 0) p['gradnormsq'] = 0.0 for in range(numiterations): for i in range(len(particles)): neighbors = getneighbors([p['pos'] for p in particles], i, kernelradius) crho = -1.0 gradsumi = Vector3(0, 0, 0) for j in neighbors: diff = particles[i]['pos'] - particles[j]['pos'] gradW = computekernelgradient(diff, kernelradius) factor = particles[j]['mass'] / restdensity crho += factor computekernel(diff, kernelradius) gradsumi += factor gradW # Accumulate gradient norm squared for neighbor j gradnormjsq = factor2 gradW.dot(gradW) particles[j]['gradnormsq'] += gradnormjsq # Compute gradient norm squared for particle i gradnormisq = 0.0 for j in neighbors: diff = particles[i]['pos'] - particles[j]['pos'] gradW = computekernelgradient(diff, kernelradius) factor = particles[j]['mass'] / restdensity gradnormisq += factor2 gradW.dot(gradW) # Solve for Delta Lambda denom = dt2 (gradnormisq / particles[i]['mass'] + particles[i]['gradnormsq'] / particles[i]['mass']) alpha = 0.0 # Hard constraint for standard PBF if denom > 1e-8: deltalambda = -crho / (denom + alpha) else: deltalambda = 0.0 # Apply Delta Lambda to position deltas particles[i]['posdelta'] += (deltalambda / particles[i]['mass']) gradsumi for j in neighbors: diff = particles[i]['pos'] - particles[j]['pos'] gradW = computekernelgradient(diff, kernelradius) factor = particles[j]['mass'] / restdensity gradsumj = -factor gradW particles[j]['posdelta'] += (deltalambda / particles[j]['mass']) gradsumj # Apply accumulated deltas to positions for p in particles